INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0084-a04-014-1', 'p0084', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '昭欲詣漢獻帝，至河內，為張楊所留。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0084-a04-031-2', 'p0084', 'sanguozhi', 'a04-031', '《三國志·蜀書一》', '漢獻帝春秋曰：漢朝聞益州亂，遣五官中郎將牛亶為益州刺史；徵璋為卿，不至。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0084-a04-046-3', 'p0084', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '江表傳曰：案漢獻帝起居注云「天子從河上還，得六璽於閣上」，又太康之初孫皓送金璽六枚，無有玉，明其偽也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0084-a05-014-4', 'p0084', 'jinshu', 'a05-014', '《晉書·卷十四》', '西海郡故屬張掖，漢獻帝興平二年，武威太守張雅請置。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0084-a05-015-5', 'p0084', 'jinshu', 'a05-015', '《晉書·卷十五》', '後漢獻帝建安十三年，魏武盡得荊州之地，分南郡以北立襄陽郡，又分南陽西界立南鄉郡，分枝江以西立臨江郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0084-a05-019-6', 'p0084', 'jinshu', 'a05-019', '《晉書·卷十九》', '司徒荀組據漢獻帝都許即便立郊，自宜於此脩奉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0084-a05-019-7', 'p0084', 'jinshu', 'a05-019', '《晉書·卷十九》', '漢獻帝建安十八年五月，以河北十郡封魏武帝為魏公。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-008-full-0', 'p0085', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '三月戊申，以河南尹何進為大將軍，將兵屯都亭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-008-full-1', 'p0085', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '後將軍袁隗為太傅，與大將軍何進參錄尚書事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-008-full-2', 'p0085', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '八月戊辰，中常侍張讓、段珪等殺大將軍何進，於是虎賁中郎將袁術燒東西宮，攻諸宦者。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-008-full-3', 'p0085', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '何進部曲將吳匡與車騎將軍何苗戰於朱雀闕下，苗敗斬之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-008-4', 'p0085', 'houhanshu', 'a03-008', '《後漢書·卷八》', '三月戊申，以河南尹何進為大將軍，將兵屯都亭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-008-5', 'p0085', 'houhanshu', 'a03-008', '《後漢書·卷八》', '後將軍袁隗為太傅，與大將軍何進參錄尚書事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-008-6', 'p0085', 'houhanshu', 'a03-008', '《後漢書·卷八》', '八月戊辰，中常侍張讓、段珪等殺大將軍何進，於是虎賁中郎將袁術燒東西宮，攻諸宦者。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-008-7', 'p0085', 'houhanshu', 'a03-008', '《後漢書·卷八》', '何進部曲將吳匡與車騎將軍何苗戰於朱雀闕下，苗敗斬之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-010b-full-8', 'p0085', 'houhanshu', 'a03-010b-full', '《後漢書·卷十下》', '何進遂舉兵圍驃騎府，收重，重免官自殺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-031-9', 'p0085', 'houhanshu', 'a03-031', '《後漢書·卷三十一》', '靈帝崩，大將軍何進表琮為度遼將軍，卒於官。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-035-10', 'p0085', 'houhanshu', 'a03-035', '《後漢書·卷三十五》', '靈帝末，黨禁解，大將軍何進聞而辟之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-037-11', 'p0085', 'houhanshu', 'a03-037', '《後漢書·卷三十七》', '靈帝崩，大將軍何進秉政，典與同謀議，三遷羽林中郎將。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-037-12', 'p0085', 'houhanshu', 'a03-037', '《後漢書·卷三十七》', '獻帝即位，三公奏典前與何進謀誅閹官，功雖不遂，忠義炳著。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-053-13', 'p0085', 'houhanshu', 'a03-053', '《後漢書·卷五十三》', '大將軍何進連徵不詣，進必欲致之，使蟠同郡黃忠書勸曰：「前莫府初開，至如先生，特加殊禮，優而不名，申以手筆，設几杖之坐。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-056-14', 'p0085', 'houhanshu', 'a03-056', '《後漢書·卷五十六》', '子謙，為大將軍何進長史。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-056-15', 'p0085', 'houhanshu', 'a03-056', '《後漢書·卷五十六》', '大將軍何進將誅宦官，召并州牧董卓，至澠池，而進意更狐疑，遣劭宣詔止之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-058-16', 'p0085', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '何進令於本州募兵，得千餘人，因留上黨擊山賊。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-062-17', 'p0085', 'houhanshu', 'a03-062', '《後漢書·卷六十二》', '後公車徵為大將軍何進從事中郎。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-062-18', 'p0085', 'houhanshu', 'a03-062', '《後漢書·卷六十二》', '及黨禁始解，大將軍何進、司徒袁隗遣人敦寔，敦，勸也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-062-19', 'p0085', 'houhanshu', 'a03-062', '《後漢書·卷六十二》', '何進遣使弔祭，海內赴者三萬餘人，制衰麻者以百數。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-062-20', 'p0085', 'houhanshu', 'a03-062', '《後漢書·卷六十二》', '先賢行狀曰：「將軍何進遣官屬弔祠為謚。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-064-21', 'p0085', 'houhanshu', 'a03-064', '《後漢書·卷六十四》', '帝崩，大將軍何進謀誅中官，乃召并州牧董卓，以懼太后。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-064-22', 'p0085', 'houhanshu', 'a03-064', '《後漢書·卷六十四》', '當植抽白刃嚴閤之下，追帝河津之閒，排戈刃，赴戕折，事見何進傳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-064-23', 'p0085', 'houhanshu', 'a03-064', '《後漢書·卷六十四》', '大將軍何進舉為敦煌太守，行至襄武，縣名，屬隴西郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-066-24', 'p0085', 'houhanshu', 'a03-066', '《後漢書·卷六十六》', '大將軍何進、太尉袁隗、司徒楊賜共上疏請之曰：「夫內視反聽，則忠臣竭誠；寬賢矜能，則義士厲節。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-066-25', 'p0085', 'houhanshu', 'a03-066', '《後漢書·卷六十六》', '時大將軍何進欲誅宦官，召允與謀事，請為從事中郎，轉河南尹。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-069-26', 'p0085', 'houhanshu', 'a03-069', '《後漢書·卷六十九》', '何進字遂高，南陽宛人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-069-27', 'p0085', 'houhanshu', 'a03-069', '《後漢書·卷六十九》', '」中黃門以進頭擲與尚書，曰：「何進謀反，已伏誅矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-069-28', 'p0085', 'houhanshu', 'a03-069', '《後漢書·卷六十九》', '論曰：竇武、何進藉元舅之資，據輔政之權，內倚太后臨朝之威，外迎羣英乘風之埶，卒而事敗閹豎，身死功穨，為世所悲，豈智不足而權有餘乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-070-29', 'p0085', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '及大將軍何進輔政，徵用名士，以公業為尚書侍郎，續漢志曰：「尚書凡六曹，侍郎三十六人，四百石。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-070-30', 'p0085', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '河南尹何進當遷為大將軍，楊賜遣融奉謁賀進，不時通，融即奪謁還府，投劾而去。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-072-31', 'p0085', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '及帝崩，大將軍何進、司隷校尉袁紹謀誅閹宦，而太后不許，乃私呼卓將兵入朝，以脅太后。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-072-32', 'p0085', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '」卓未至而何進敗，虎賁中郎將袁術乃燒南宮，欲討宦官，而中常侍段珪等山陽公載記「段」字作「殷」。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-072-33', 'p0085', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '尋而何進及弟苗先所領部曲皆歸於卓，卓又使呂布殺執金吾丁原而并其衆，英雄記曰：「原字建陽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-073-34', 'p0085', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '紹不能舉直措枉，而專為邪媚，招來不軌，疑誤社稷，至令丁原焚燒孟津，續漢書曰：「何進欲誅中常侍趙忠等，進乃詐令武猛都尉丁原放兵數千人，為賊於河內，稱『黑山伯』，上事以誅忠等為辭，燒平陰、河津莫府人舍，以怖動太后。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-074-35', 'p0085', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '後辟大將軍何進掾，為侍御史、虎賁中郎將。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-074-36', 'p0085', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '靈帝崩，紹勸何進徵董卓等衆軍，脅太后誅諸宦官，轉紹司隷校尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-074-37', 'p0085', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '故大將軍何進忠國疾亂，義心赫怒，以臣頗有一介之節，可責以鷹犬之功，故授臣以督司，諮臣以方略。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-074-38', 'p0085', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '忠策未盡而元帥受敗，元帥謂何進。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-075-39', 'p0085', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '靈帝崩，原受何進召，將兵詣洛陽，為執金吾。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-078-40', 'p0085', 'houhanshu', 'a03-078', '《後漢書·卷七十八》', '竇武、何進，位崇戚近，乘九服之嚻怨，協羣英之埶力，九服已見上。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-078-41', 'p0085', 'houhanshu', 'a03-078', '《後漢書·卷七十八》', '中軍校尉袁紹說大將軍何進，令誅中官以恱天下。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-080b-42', 'p0085', 'houhanshu', 'a03-080b', '《後漢書·卷八十下》', '大將軍何進聞讓才名，欲辟命之，恐不至，詭以軍事徵召，旣到，署令史，續漢志曰：「大將軍下有令史及御史屬三十一人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-080b-43', 'p0085', 'houhanshu', 'a03-080b', '《後漢書·卷八十下》', '議郎蔡邕深敬之，以為讓宜處高任，乃薦於何進曰：「伏惟幕府初開，博選清英，華髮舊德，並為元龜。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-081-44', 'p0085', 'houhanshu', 'a03-081', '《後漢書·卷八十一》', '大將軍何進移書陳留太守，累行論謚，僉曰宜為貞節先生。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-102-45', 'p0085', 'houhanshu', 'a03-102', '《二十四史-後漢書-志第十二‧天文下》', '中平六年，宮車晏駕，大將軍何進令司隷校尉袁紹私募兵千餘人，陰跱雒陽城外，竊呼并州牧董卓使將兵至京都，共誅中官，對戰南、北宮闕下，死者數千人，燔燒宮室，遷都西京。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-102-46', 'p0085', 'houhanshu', 'a03-102', '《二十四史-後漢書-志第十二‧天文下》', '」中平六年，大將軍何進謀盡誅中官，中官覺，於省中殺進：俱兩破滅，天下由此遂大壞亂。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-102-47', 'p0085', 'houhanshu', 'a03-102', '《二十四史-後漢書-志第十二‧天文下》', '其日未冥四刻，大將軍何進於省中為諸黃門所殺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-103-48', 'p0085', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '是時靈帝新棄羣臣，大行尚在梓宮，大將軍何進與佐軍校尉袁紹等共謀欲誅廢中官。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-103-49', 'p0085', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '皇后同父兄何進為大將軍，同母弟苗為車騎將軍，兄弟並貴盛，皆統兵在京都。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-104-50', 'p0085', 'houhanshu', 'a03-104', '《二十四史-後漢書-志第十四‧五行二》', '皇后兄何進，異父兄朱苗，皆為將軍，領兵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a03-104-51', 'p0085', 'houhanshu', 'a03-104', '《二十四史-後漢書-志第十四‧五行二》', '到六年，靈帝崩，大將軍何進以內寵外嬖，積惡日乆，欲悉糾黜，以隆更始冗政，而太后持疑，事乆不決。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a04-001-52', 'p0085', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '大將軍何進與袁紹謀誅宦官，太后不聽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a04-001-53', 'p0085', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '辟大將軍何進府進符使，匡於徐州發彊弩五百西詣京師。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a04-001-54', 'p0085', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '遂奉計詣京師，何進宿聞其名，特與相見，遂說進使誅諸閹人，進不從，乃求歸。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a04-006-55', 'p0085', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '」卓再違詔勑，會為何進所召。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a04-006-56', 'p0085', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '大將軍何進與司隷校尉袁紹謀誅諸閹官，太后不從。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a04-006-57', 'p0085', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '後大將軍何進辟為東曹屬，稍遷侍中、河南尹、越騎校尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a04-006-58', 'p0085', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '靈帝崩，太后兄大將軍何進與紹謀誅諸閹官，續漢書曰：紹使客張津說進曰：「黃門、常侍秉權日乆，又永樂太后與諸常侍專通財利，將軍宜整頓天下，為海內除患。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a04-006-59', 'p0085', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '大將軍何進聞其名，辟為東曹掾。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a04-007-60', 'p0085', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '與何進謀誅諸黃門，拜執金吾。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a04-008-61', 'p0085', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '靈帝崩，碩為何進所殺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a04-010-62', 'p0085', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '何進秉政，徵海內名士攸等二十餘人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a04-012-63', 'p0085', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '勛父信，靈帝時為騎都尉，大將軍何進遣東募兵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a04-012-64', 'p0085', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '大將軍何進辟拜騎都尉，遣歸募兵，得千餘人，還到成皐而進已遇害。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a04-013-65', 'p0085', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '靈帝崩，何進輔政，徵河南鄭泰、潁川荀攸及歆等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a04-016-66', 'p0085', 'sanguozhi', 'a04-016', '《三國志·魏書十六》', '何進輔政，徵用名士，以泰為尚書侍郎，加奉車都尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a04-017-67', 'p0085', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '何進遣詣河北募兵，得千餘人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a04-021-68', 'p0085', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '父謙，為大將軍何進長史。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a04-022-69', 'p0085', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '靈帝崩，何進輔政，引用天下名士，徵寔，欲以為參軍，以老病，遂不屈節，諶為司空掾，早卒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a04-022-70', 'p0085', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '先賢行狀曰：大將軍何進遣屬弔祠，謚曰文範先生。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a04-031-71', 'p0085', 'sanguozhi', 'a04-031', '《三國志·蜀書一》', '大將軍何進表薦扶曰：「資游、夏之德，述孔氏之風，內懷焦、董消復之術。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a04-032-72', 'p0085', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '頃之，大將軍何進遣都尉毌丘毅詣丹楊募兵，先主與俱行，至下邳遇賊，力戰有功，除為下密丞。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a04-045-73', 'p0085', 'sanguozhi', 'a04-045', '《三國志·蜀書十五》', '壹族弟班，字元雄，大將軍何進官屬吳匡之子也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0085-a04-053-74', 'p0085', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '還本郡，舉茂才，公府辟，皆不就，吳書曰：大將軍何進、太尉朱儁、司空荀爽三府辟為掾，皆稱疾不就。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a03-009-0', 'p0086', 'houhanshu', 'a03-009', '《後漢書·卷九》', '獻帝起居注曰：「自誅黃門後，侍中、侍郎出入禁中，機事頗露，由是王允乃奏侍中、黃門不得出入。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a03-009-1', 'p0086', 'houhanshu', 'a03-009', '《後漢書·卷九》', '司徒王允錄尚書事，揔朝政，遣使者張种撫慰山東。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a03-009-2', 'p0086', 'houhanshu', 'a03-009', '《後漢書·卷九》', '李傕殺司隷校尉黃琬，甲子，殺司徒王允，皆滅其族。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a03-025-3', 'p0086', 'houhanshu', 'a03-025', '《後漢書·卷二十五》', '謙子旭，官至太僕，從獻帝西入關，與司徒王允同謀共誅董卓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a03-027-4', 'p0086', 'houhanshu', 'a03-027', '《後漢書·卷二十七》', '李傕殺司徒王允，復代允為司徒，數月病免，拜尚書令。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a03-058-5', 'p0086', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '卓問司徒王允曰：「欲得快司隷校尉，誰可作者？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a03-061-6', 'p0086', 'houhanshu', 'a03-061', '《後漢書·卷六十一》', '後與楊彪同拜光祿大夫，及徙西都，轉司隷校尉，與司徒王允同謀誅卓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a03-062-7', 'p0086', 'houhanshu', 'a03-062', '《後漢書·卷六十二》', '爽見董卓忍暴滋甚，必危社稷，其所辟舉皆取才略之士，將共圖之，亦與司徒王允及卓長史何顒等為內謀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a03-066-8', 'p0086', 'houhanshu', 'a03-066', '《後漢書·卷六十六》', '王允字子師，太原祁人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a03-066-9', 'p0086', 'houhanshu', 'a03-066', '《後漢書·卷六十六》', '若王允之推董卓而引其權，伺其閒而敝其罪，當此之時，天子懸解矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a03-067-10', 'p0086', 'houhanshu', 'a03-067', '《後漢書·卷六十七》', '及董卓秉政，逼顒以為長史，託疾不就，乃與司空荀爽、司徒王允等共謀卓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a03-069-11', 'p0086', 'houhanshu', 'a03-069', '《後漢書·卷六十九》', '」進於是以紹為司隷校尉，假節，專命擊斷；從事中郎王允為河南尹。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a03-069-12', 'p0086', 'houhanshu', 'a03-069', '《後漢書·卷六十九》', '公卿並出平樂觀，無得從者，唯尚書盧植夜馳河上，王允遣河南中部掾閔貢隨植後。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a03-072-13', 'p0086', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '」少有名譽，累登公卿，亦陰與司徒王允共謀誅卓，事未及發而見害。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a03-072-14', 'p0086', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '時王允與呂布及僕射士孫瑞謀誅卓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a03-072-15', 'p0086', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '王允乃與士孫瑞密表其事，使瑞自書詔以授布，令騎都尉李肅獻帝紀曰：「肅，呂布同郡人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a03-072-16', 'p0086', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '傕、汜等以王允、呂布殺董卓，故忿怒并州人，并州人其在軍者男女數百人，皆誅殺之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a03-072-17', 'p0086', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '王允以為一歲不可再赦，不許之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a03-072-18', 'p0086', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '王允聞之，乃遣卓故將胡軫、徐榮擊之於新豐。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a03-072-19', 'p0086', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '九州春秋曰：「胡文才、楊整脩皆涼州人，王允素所不善也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a03-072-20', 'p0086', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '王允奉天子保宣平城門樓上。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a03-072-21', 'p0086', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '遂圍門樓，共表請司徒王允出，問「太師何罪」？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a03-075-22', 'p0086', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '因往見司徒王允，自陳卓幾見殺之狀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a03-079-23', 'p0086', 'houhanshu', 'a03-079', '《後漢書·卷七十九上》', '」及王允所收而西者，裁七十餘乘，道路艱遠，復弃其半矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a03-102-24', 'p0086', 'houhanshu', 'a03-102', '《二十四史-後漢書-志第十二‧天文下》', '及司徒王允與將軍呂布誅卓，卓部曲將郭汜、李傕旋兵攻長安，公卿百官吏民戰死者且萬人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a03-103-25', 'p0086', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '至三年夏，司徒王允使中郎將呂布殺太師董卓，夷三族。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a03-116-26', 'p0086', 'houhanshu', 'a03-116', '《二十四史-後漢書-志第二十六‧百官三》', '誅黃門後，侍中、侍郎出入禁闈，機事頗露，由是王允乃奏比尚書，不得出入，不通賔客，自此始也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a04-001-27', 'p0086', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '夏四月，司徒王允與呂布共殺卓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a04-006-28', 'p0086', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '三年四月，司徒王允、尚書僕射士孫瑞、卓將呂布共謀誅卓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a04-006-29', 'p0086', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '謝承後漢書曰：蔡邕在王允坐，聞卓死，有歎惜之音。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a04-006-30', 'p0086', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '縱復令然，不應反言於王允之坐。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a04-006-31', 'p0086', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '史遷紀傳，博有奇功於世，而云王允謂孝武應早殺遷，此非識者之言。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a04-006-32', 'p0086', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '王允之忠正，可謂內省不疚者矣，旣無懼於謗，且欲殺邕，當論邕應死與不，豈可慮其謗己而枉戮善人哉！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a04-006-33', 'p0086', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '胡文才、楊整脩皆涼州大人，而司徒王允素所不善也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a04-006-34', 'p0086', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '誅殺卓者，尸王允於市。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a04-006-35', 'p0086', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '司徒王允扶天子上宣平城門避兵，傕等於城門下拜，伏地叩頭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a04-006-36', 'p0086', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '華嶠曰：夫士以正立，以謀濟，以義成，若王允之推董卓而分其權，伺其間而弊其罪。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a04-007-37', 'p0086', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '先是，司徒王允以布州里壯健，厚接納之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a04-014-38', 'p0086', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '講業太學，博覽傳記，同郡王允一見而奇之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a04-016-39', 'p0086', 'sanguozhi', 'a04-016', '《三國志·魏書十六》', '後又與王允謀共誅卓，泰脫身自武關走，東歸。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a04-032-40', 'p0086', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '故將王允被害，莫敢近者，戩棄官收歛之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a05-003-41', 'p0086', 'jinshu', 'a05-003', '《晉書·卷三》', '改封南陽王柬為秦王，始平王瑋為楚王，濮陽王允為淮南王，並假節之國，各統方州軍事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a05-003-42', 'p0086', 'jinshu', 'a05-003', '《晉書·卷三》', '說者紛然，久而不定，竟用王佑之謀，遣太子母弟秦王柬都督關中，楚王瑋、淮南王允並鎮守要害，以彊帝室。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a05-004-43', 'p0086', 'jinshu', 'a05-004', '《晉書·卷四》', '癸酉，鎮南將軍楚王瑋、鎮東將軍淮南王允來朝。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a05-004-44', 'p0086', 'jinshu', 'a05-004', '《晉書·卷四》', '丁酉，以梁王肜為太宰，左光祿大夫何劭為司徒，右光祿大夫劉寔為司空，淮南王允為驃騎將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a05-004-45', 'p0086', 'jinshu', 'a05-004', '《晉書·卷四》', '秋八月，淮南王允舉兵討趙王倫，不剋，允及其二子秦王郁、漢王迪皆遇害。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a05-007-46', 'p0086', 'jinshu', 'a05-007', '《晉書·卷七》', '乙未，將軍王允之及逸戰於溧陽，獲之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a05-007-47', 'p0086', 'jinshu', 'a05-007', '《晉書·卷七》', '癸丑，帝觀兵于廣莫門，分命諸將，遣將軍劉仕救歷陽，平西將軍趙胤屯慈湖，龍驤將軍路永戍牛渚，建武將軍王允之戍蕪湖。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a05-007-48', 'p0086', 'jinshu', 'a05-007', '《晉書·卷七》', '庾懌嘗送酒於江州刺史王允之，允之與犬，犬斃，懼而表之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a05-007-49', 'p0086', 'jinshu', 'a05-007', '《晉書·卷七》', '以江州刺史王允之為衞將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a05-007-50', 'p0086', 'jinshu', 'a05-007', '《晉書·卷七》', '冬十月甲午，衞將軍王允之卒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0086-a05-037-51', 'p0086', 'jinshu', 'a05-037', '《晉書-卷三十七・列傳第七》', '出爲安東將軍、都督揚州諸軍事，代淮南王允鎮壽春，未發。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-008-full-0', 'p0087', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '遣中郎將董卓攻張角，不剋。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-008-full-1', 'p0087', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '又遣中郎將董卓討先零羌。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-008-full-2', 'p0087', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '并州牧董卓殺執金吾丁原。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-008-full-3', 'p0087', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '司空劉弘免，董卓自為司空。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-008-full-4', 'p0087', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '九月甲戌，董卓廢帝為弘農王。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-008-5', 'p0087', 'houhanshu', 'a03-008', '《後漢書·卷八》', '遣中郎將董卓攻張角，不剋。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-008-6', 'p0087', 'houhanshu', 'a03-008', '《後漢書·卷八》', '又遣中郎將董卓討先零羌。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-008-7', 'p0087', 'houhanshu', 'a03-008', '《後漢書·卷八》', '并州牧董卓殺執金吾丁原。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-008-8', 'p0087', 'houhanshu', 'a03-008', '《後漢書·卷八》', '司空劉弘免，董卓自為司空。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-008-9', 'p0087', 'houhanshu', 'a03-008', '《後漢書·卷八》', '九月甲戌，董卓廢帝為弘農王。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-009-10', 'p0087', 'houhanshu', 'a03-009', '《後漢書·卷九》', '丙子，董卓殺皇太后何氏。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-009-11', 'p0087', 'houhanshu', 'a03-009', '《後漢書·卷九》', '董卓自為太尉，加鈇鉞、虎賁。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-009-12', 'p0087', 'houhanshu', 'a03-009', '《後漢書·卷九》', '」董卓遣其將牛輔擊之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-009-13', 'p0087', 'houhanshu', 'a03-009', '《後漢書·卷九》', '十一月癸酉，董卓為相國。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-009-14', 'p0087', 'houhanshu', 'a03-009', '《後漢書·卷九》', '初平元年春正月，山東州郡起兵以討董卓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-009-15', 'p0087', 'houhanshu', 'a03-009', '《後漢書·卷九》', '庚辰，董卓殺城門校尉伍瓊、督軍校尉周珌。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-009-16', 'p0087', 'houhanshu', 'a03-009', '《後漢書·卷九》', '董卓驅徙京師百姓悉西入關，自留屯畢圭苑。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-009-17', 'p0087', 'houhanshu', 'a03-009', '《後漢書·卷九》', '」己酉，董卓焚洛陽宮廟及人家。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-009-18', 'p0087', 'houhanshu', 'a03-009', '《後漢書·卷九》', '戊午，董卓殺太傅袁隗、太僕袁基，夷其族。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-009-19', 'p0087', 'houhanshu', 'a03-009', '《後漢書·卷九》', '董卓壞五銖錢，更鑄小錢。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-009-20', 'p0087', 'houhanshu', 'a03-009', '《後漢書·卷九》', '二月丁丑，董卓自為太師。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-009-21', 'p0087', 'houhanshu', 'a03-009', '《後漢書·卷九》', '袁術遣將孫堅與董卓將胡軫戰於陽人，陽人，聚名，屬河南郡，故城在今汝州梁縣西。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-009-22', 'p0087', 'houhanshu', 'a03-009', '《後漢書·卷九》', '董卓遂發掘洛陽諸帝陵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-009-23', 'p0087', 'houhanshu', 'a03-009', '《後漢書·卷九》', '冬十月壬戌，董卓殺衞尉張溫。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-009-24', 'p0087', 'houhanshu', 'a03-009', '《後漢書·卷九》', '夏四月辛巳，誅董卓，夷三族。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-009-25', 'p0087', 'houhanshu', 'a03-009', '《後漢書·卷九》', '董卓部曲將李傕、郭汜、樊稠、張濟等反，攻京師。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-010b-full-26', 'p0087', 'houhanshu', 'a03-010b-full', '《後漢書·卷十下》', '并州牧董卓被徵，將兵入洛陽，陵虐朝庭，遂廢少帝為弘農王而立協，是為獻帝。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-010b-full-27', 'p0087', 'houhanshu', 'a03-010b-full', '《後漢書·卷十下》', '董卓又議太后踧迫永樂宮，至令憂死，逆婦姑之禮，乃遷於永安宮，因進酖，弒而崩。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-010b-full-28', 'p0087', 'houhanshu', 'a03-010b-full', '《後漢書·卷十下》', '董卓令帝出奉常亭舉哀，華延儁洛陽記曰：「城內有奉常亭。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-010b-full-29', 'p0087', 'houhanshu', 'a03-010b-full', '《後漢書·卷十下》', '明年，山東義兵大起，討董卓之亂。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-025-30', 'p0087', 'houhanshu', 'a03-025', '《後漢書·卷二十五》', '謙子旭，官至太僕，從獻帝西入關，與司徒王允同謀共誅董卓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-027-31', 'p0087', 'houhanshu', 'a03-027', '《後漢書·卷二十七》', '車師王侍子為董卓所愛，數犯法，謙收殺之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-035-32', 'p0087', 'houhanshu', 'a03-035', '《後漢書·卷三十五》', '董卓遷都長安，公卿舉玄為趙相，道斷不至。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-036-33', 'p0087', 'houhanshu', 'a03-036', '《後漢書·卷三十六》', '及董卓秉政，聞之，辟以為掾，舉侍御史，不就。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-045-34', 'p0087', 'houhanshu', 'a03-045', '《後漢書·卷四十五》', '董卓忿紹、術背己，遂誅隗及術兄基男女二十餘人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-045-35', 'p0087', 'houhanshu', 'a03-045', '《後漢書·卷四十五》', '及帝崩，暉聞京師不安，來候忠，董卓聞而惡之，使兵劫殺其兄弟。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-048-36', 'p0087', 'houhanshu', 'a03-048', '《後漢書·卷四十八》', '逆臣董卓，蕩覆王室，典憲焚燎，靡有孑遺，開辟以來，莫或茲酷。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-048-37', 'p0087', 'houhanshu', 'a03-048', '《後漢書·卷四十八》', '孫堅從桂陽入雒討董卓，軍於城南，見井中有五色光，軍人莫敢汲，堅乃浚得璽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-049-38', 'p0087', 'houhanshu', 'a03-049', '《後漢書·卷四十九》', '孝靈遭黃巾之寇，獻帝嬰董卓之禍，英雄棋峙，白骨膏野，兵亂相尋三十餘年，三方旣寧，萬不存一也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-052-39', 'p0087', 'houhanshu', 'a03-052', '《後漢書·卷五十二》', '獻帝初，鈞與袁紹俱起兵山東，董卓以是收烈付郿獄，錮之，鋃鐺鐵鎖。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-053-40', 'p0087', 'houhanshu', 'a03-053', '《後漢書·卷五十三》', '明年，董卓廢立，蟠及爽、融、紀等復俱公車徵，續漢志曰，徵爽為司空，融為尚書，紀為侍中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-054-41', 'p0087', 'houhanshu', 'a03-054', '《後漢書·卷五十四》', '中平六年，代董卓為司空，其冬，代黃琬為司徒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-054-42', 'p0087', 'houhanshu', 'a03-054', '《後漢書·卷五十四》', '明年，關東兵起，董卓懼，欲遷都以違其難。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-056-43', 'p0087', 'houhanshu', 'a03-056', '《後漢書·卷五十六》', '大將軍何進將誅宦官，召并州牧董卓，至澠池，而進意更狐疑，遣劭宣詔止之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-058-44', 'p0087', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '及帝崩，董卓廢少帝，殺何太后，勳與書曰：「昔伊尹、霍光權以立功，猶可寒心，足下小醜，何以終此？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-058-45', 'p0087', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '時董卓殺帝，圖危社稷。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-058-46', 'p0087', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '洪乃攝衣升壇，操血而盟曰：「漢室不幸，皇綱失統，賊臣董卓，乘釁縱害，禍加至尊，毒流百姓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-061-47', 'p0087', 'houhanshu', 'a03-061', '《後漢書·卷六十一》', '及董卓秉政，以琬名臣，徵為司徒，遷太尉，更封陽泉鄉侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-062-48', 'p0087', 'houhanshu', 'a03-062', '《後漢書·卷六十二》', '獻帝即立，董卓輔政，復徵之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-062-49', 'p0087', 'houhanshu', 'a03-062', '《後漢書·卷六十二》', '爽見董卓忍暴滋甚，必危社稷，其所辟舉皆取才略之士，將共圖之，亦與司徒王允及卓長史何顒等為內謀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-062-50', 'p0087', 'houhanshu', 'a03-062', '《後漢書·卷六十二》', '及董卓當朝，復備禮召之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-062-51', 'p0087', 'houhanshu', 'a03-062', '《後漢書·卷六十二》', '董卓入洛陽，乃使就家拜五官中郎將，不得已，到京師，遷侍中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-064-52', 'p0087', 'houhanshu', 'a03-064', '《後漢書·卷六十四》', '帝崩，大將軍何進謀誅中官，乃召并州牧董卓，以懼太后。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-065-53', 'p0087', 'houhanshu', 'a03-065', '《後漢書·卷六十五》', '奐遣司馬尹端、董卓並擊，大破之，斬其酋豪，首虜萬餘人，三州清定。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-065-54', 'p0087', 'houhanshu', 'a03-065', '《後漢書·卷六十五》', '董卓慕之，使其兄遺縑百匹。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-066-55', 'p0087', 'houhanshu', 'a03-066', '《後漢書·卷六十六》', '及董卓遷都關中，允悉收斂蘭臺、石室圖書秘緯要者以從。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-066-56', 'p0087', 'houhanshu', 'a03-066', '《後漢書·卷六十六》', '時董卓尚留洛陽，朝政大小悉委之於允。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-066-57', 'p0087', 'houhanshu', 'a03-066', '《後漢書·卷六十六》', '初懼董卓豺狼，故折節圖之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-066-58', 'p0087', 'houhanshu', 'a03-066', '《後漢書·卷六十六》', '董卓將校及在位者多涼州人，允議罷其軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-066-59', 'p0087', 'houhanshu', 'a03-066', '《後漢書·卷六十六》', '」宏曰：「義兵鼎沸，在於董卓，況其黨與乎！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-066-60', 'p0087', 'houhanshu', 'a03-066', '《後漢書·卷六十六》', '瑞以允自專討董卓之勞，故歸功不侯，所以獲免於難。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-066-61', 'p0087', 'houhanshu', 'a03-066', '《後漢書·卷六十六》', '董卓數欲有所私授，戩輒堅拒不聽，言色強厲。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-066-62', 'p0087', 'houhanshu', 'a03-066', '《後漢書·卷六十六》', '若王允之推董卓而引其權，伺其閒而敝其罪，當此之時，天子懸解矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-067-63', 'p0087', 'houhanshu', 'a03-067', '《後漢書·卷六十七》', '及董卓秉政，逼顒以為長史，託疾不就，乃與司空荀爽、司徒王允等共謀卓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-069-64', 'p0087', 'houhanshu', 'a03-069', '《後漢書·卷六十九》', '太史奏言有大臣誅死，董卓取溫笞殺於市以厭之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-069-65', 'p0087', 'houhanshu', 'a03-069', '《後漢書·卷六十九》', '遂西召前將軍董卓屯關中上林苑，又使府掾太山王匡東發其郡強弩，并召東郡太守橋瑁屯城皐，使武猛都尉丁原燒孟津，武猛謂有武蓺而勇猛者。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-069-66', 'p0087', 'houhanshu', 'a03-069', '《後漢書·卷六十九》', '紹使洛陽方略武吏司察宦者，而促董卓等使馳驛上，欲進兵平樂觀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-069-67', 'p0087', 'houhanshu', 'a03-069', '《後漢書·卷六十九》', '今董卓垂至，諸君何不早各就國？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-069-68', 'p0087', 'houhanshu', 'a03-069', '《後漢書·卷六十九》', '」匡遂引兵與董卓弟奉車都尉旻攻殺苗，弃其屍於苑中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-069-69', 'p0087', 'houhanshu', 'a03-069', '《後漢書·卷六十九》', '董卓遂廢帝，又迫殺太后，殺舞陽君，何氏遂亡，而漢室亦自此敗亂。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-070-70', 'p0087', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '進將誅閹官，欲召并州牧董卓為助。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-070-71', 'p0087', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '公業謂進曰：「董卓彊忍寡義，志欲無猒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-070-72', 'p0087', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '會董卓廢立，融每因對荅，輒有匡正之言。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-070-73', 'p0087', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '董卓之亂，弃官歸鄉里。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-070-74', 'p0087', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '會兾州牧同郡韓馥遣騎迎之，彧乃獨將宗族從馥，留者後多為董卓將李傕所殺略焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-070-75', 'p0087', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '初，紹去董卓，與許攸及紀俱詣兾州，紹以紀聦達有計策，甚信之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-071-76', 'p0087', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '時北中郎將盧植及東中郎將董卓討張角，並無功而還，乃詔嵩進兵討之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-071-77', 'p0087', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '五年，涼州賊王國圍陳倉，復拜嵩為左將軍，督前將軍董卓，各率二萬人拒之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-071-78', 'p0087', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '時在軍中，說嵩曰：「本朝失政，天下倒懸，能安危定傾者，唯大人與董卓耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-071-79', 'p0087', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '嵩將行，長史梁衍說曰：「漢室微弱，閹豎亂朝，董卓雖誅之，而不能盡忠於國，遂復寇掠京邑，廢立從意。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-071-80', 'p0087', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '時董卓擅政，以儁宿將，外甚親納而心實忌之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-071-81', 'p0087', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '」儁曰：「相國董卓具為臣說，所以知耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-071-82', 'p0087', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '董卓聞之，使其將李傕、郭汜等數萬人屯河南拒儁。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-071-83', 'p0087', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '及董卓被誅，傕、汜作亂，儁時猶在中牟。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-071-84', 'p0087', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '」國家旣遭董卓，重以李傕、郭汜之禍，幼主劫執，忠良殘敝，長安隔絕，不知吉凶。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-072-85', 'p0087', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '董卓字仲穎，卓別傳曰：「卓父君雅為潁川輪氏尉，生卓及弟旻，故卓字仲穎，旻字叔穎。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-072-86', 'p0087', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '傕、汜等以王允、呂布殺董卓，故忿怒并州人，并州人其在軍者男女數百人，皆誅殺之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-072-87', 'p0087', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '傕等葬董卓於郿，并收董氏所焚尸之灰，合斂一棺而葬之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-072-88', 'p0087', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '又於朝廷省門外為董卓作神坐，數以牛羊祠之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-072-89', 'p0087', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '論曰：董卓初以虓闞為情，詩大雅曰：「闞如虓虎。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-072-90', 'p0087', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '」董卓滔天，滔，漫也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-073-91', 'p0087', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '及董卓秉政，遣使者授虞大司馬，進封襄賁侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-073-92', 'p0087', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '逼於董卓，遠隔關塞，不知存否，以虞宗室長者，欲立為主。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-073-93', 'p0087', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '紹為勃海，當攻董卓，而默選戎馬，不告父兄，至使太傅一門纍然同斃。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-073-94', 'p0087', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '董卓恨紹起兵山東，乃誅紹叔父太傅隗，及宗族在京師者，盡誅滅之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-073-95', 'p0087', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '又長沙太守孫堅，前領豫州刺史，遂能驅走董卓，埽除陵廟，忠勤王室，其功莫大。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-073-96', 'p0087', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '紹遣小將盜居其位，斷絕堅糧，不得深入，使董卓乆不服誅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-073-97', 'p0087', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '時董卓雖誅，而李傕、郭汜作亂關中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-074-98', 'p0087', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '靈帝崩，紹勸何進徵董卓等衆軍，脅太后誅諸宦官，轉紹司隷校尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-074-99', 'p0087', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '」「董卓擁制強兵，將有異志，今不早圖，必為所制。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-074-100', 'p0087', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '董卓聞紹起山東，乃誅紹叔父隗，及宗族在京師者，盡滅之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-074-101', 'p0087', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '橋瑁乃詐作三公移書，傳驛州郡，說董卓罪惡，天子危逼，企望義兵，以釋國難。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-074-102', 'p0087', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '初，紹去董卓，與許攸及紀俱詣兾州，以紀聦達有計策，甚親信之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-074-103', 'p0087', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '瓚遂引兵而至，外託討董卓，而陰謀襲馥。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-074-104', 'p0087', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '值廢立之際，忠義奮發，單騎出奔，董卓懷懼，濟河而北，勃海稽服。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-074-105', 'p0087', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '會董卓乘虛，所圖不軌。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-074-106', 'p0087', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '山陽公載記曰：「董卓以紹為前將軍，封邟鄉侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-074-107', 'p0087', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '獻帝春秋曰：「紹合兾州十郡守相，衆數十萬，登壇歃血，盟曰：『賊臣董卓，承漢室之微，負兵甲之衆，陵越帝城，跨蹈王朝，幽鴆太后，戮殺弘農，提挈幼主，越遷秦地，殘害朝臣，斬刈忠良，焚燒宮室，蒸亂宮人，發掘陵墓，虐及鬼神，過惡烝皇天，濁穢薰后土。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-074-108', 'p0087', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '續遇董卓侵官暴國，左傳：「侵官冒也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-074-109', 'p0087', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '續漢書曰：「彪代董卓為司空，又代黃琬為司徒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-075-110', 'p0087', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '時董卓將欲廢立，以術為後將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-075-111', 'p0087', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '劉表上術為南陽太守，術又表堅領豫州刺史，使率荊、豫之卒，擊破董卓於陽人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-075-112', 'p0087', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '孫堅北討董卓，頓軍城南，甄官署有井，每旦有五色氣從井中出，使人浚井，得漢傳國玉璽，其文曰『受命于天，旣壽永昌』。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-075-113', 'p0087', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '策聞術將欲僭號，與書諫曰：「董卓無道，陵虐王室，禍加太后，暴及弘農，天子播越，左傳曰，王子朝云「茲不穀震蕩播越」。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-075-114', 'p0087', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '會進敗，董卓誘布殺原而并其兵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-075-115', 'p0087', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '董卓之亂，與曹操共舉義兵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-075-116', 'p0087', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '術欲引布擊備，乃與布書曰：「術舉兵詣闕，未能屠裂董卓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-075-117', 'p0087', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '董卓殺隗及術兄基等男女二十餘人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-075-118', 'p0087', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '」布用珪策，與暹、奉書曰：「二將軍親拔大駕，而布手殺董卓，俱立功名，當垂竹帛。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-076-119', 'p0087', 'houhanshu', 'a03-076', '《後漢書·卷七十六》', '董卓入洛陽，岱從侍中出為兖州刺史。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-079-120', 'p0087', 'houhanshu', 'a03-079', '《後漢書·卷七十九上》', '及董卓移都之際，吏民擾亂，自辟雍、東觀、蘭臺、石室、宣明、鴻都諸藏典策文章，競共剖散，其縑帛圖書，大則連為帷蓋，小乃制為縢囊。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-081-121', 'p0087', 'houhanshu', 'a03-081', '《後漢書·卷八十一》', '遭黃巾、董卓之亂，乃避地遼東，夷人尊奉之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-084-122', 'p0087', 'houhanshu', 'a03-084', '《後漢書·卷八十四》', '後董卓為相國，承其名，娉以軿輜百乘，馬二十匹，奴婢錢帛充路。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-084-123', 'p0087', 'houhanshu', 'a03-084', '《後漢書·卷八十四》', '漢季失權柄，董卓亂天常。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-096-124', 'p0087', 'houhanshu', 'a03-096', '《二十四史-後漢書-志第六‧禮儀下》', '」臣昭案：董卓傳：「卓使呂布發諸帝陵及公卿以下冢墓，收其珍寶。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-099-125', 'p0087', 'houhanshu', 'a03-099', '《二十四史-後漢書-志第九‧祭祀下》', '初平中，相國董卓、左中郎將蔡邕等以和帝以下，功德無殊，而有過差，不應為宗，及餘非宗者追尊三后，皆奏毀之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-102-126', 'p0087', 'houhanshu', 'a03-102', '《二十四史-後漢書-志第十二‧天文下》', '中平六年，宮車晏駕，大將軍何進令司隷校尉袁紹私募兵千餘人，陰跱雒陽城外，竊呼并州牧董卓使將兵至京都，共誅中官，對戰南、北宮闕下，死者數千人，燔燒宮室，遷都西京。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-103-127', 'p0087', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '其後董卓多擁胡兵，填塞街衢，虜掠宮掖，發掘園陵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-103-128', 'p0087', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '其後董卓陵虐王室，多援邊人以充本朝，胡夷異種，跨蹈中國。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-103-129', 'p0087', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '至三年夏，司徒王允使中郎將呂布殺太師董卓，夷三族。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-103-130', 'p0087', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '』」案逆臣董卓滔天虐民，窮凶極惡，關東舉兵欲共誅之，轉相顧望，莫肯先進，處處停兵數十萬，若烏臘蟲，相隨橫取之矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-103-131', 'p0087', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '」案「董」謂董卓也，言雖跋扈，縱其殘暴，終歸逃竄，至於滅族也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-104-132', 'p0087', 'houhanshu', 'a03-104', '《二十四史-後漢書-志第十四‧五行二》', '其後三年，靈帝暴崩，續以董卓之亂，火三日不絕，京都為丘墟矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-104-133', 'p0087', 'houhanshu', 'a03-104', '《二十四史-後漢書-志第十四‧五行二》', '董卓之亂，實擁胡兵，傕、汜之時，充斥尤甚，遂窺閒宮嬪，剽虐百姓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-107-134', 'p0087', 'houhanshu', 'a03-107', '《二十四史-後漢書-志第十七‧五行五》', '到光熹元年，董卓自外入，因閒乘釁，廢帝殺后，百官總己，號令自由，殺戮決前，威重於主。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-107-135', 'p0087', 'houhanshu', 'a03-107', '《二十四史-後漢書-志第十七‧五行五》', '後董卓戮太后，被以不孝之名，放廢天子，後復害之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-107-136', 'p0087', 'houhanshu', 'a03-107', '《二十四史-後漢書-志第十七‧五行五》', '陰呼并州牧董卓欲共誅中官，中官逆殺大將軍進，兵相攻討，京都戰者塞道。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-109-137', 'p0087', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '及靈帝遭黃巾，獻帝即位而董卓興亂，大焚宮廟，劫御西遷，京師蕭條，豪桀並爭，郭汜、李傕之屬，殘害又甚，是以興平、建安之際，海內凶荒，天子奔流，白骨盈野，故陝津之難，以箕撮指，安邑之東，后裳不完，遂有寇戎，雄雌未定，割剝庶民，三十餘年。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-114-138', 'p0087', 'houhanshu', 'a03-114', '《二十四史-後漢書-志第二十四‧百官一》', '董卓在長安，又自尊為太師，位在太傅上。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-114-139', 'p0087', 'houhanshu', 'a03-114', '《二十四史-後漢書-志第二十四‧百官一》', '」案獻帝方，董卓自太尉進為相國，而司徒不省。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-115-140', 'p0087', 'houhanshu', 'a03-115', '《二十四史-後漢書-志第二十五‧百官二》', '董卓為東中郎將，盧植為北中郎將，獻帝以曹植為南中郎將。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a03-120-141', 'p0087', 'houhanshu', 'a03-120', '《二十四史-後漢書-志第三十‧輿服下》', '孫堅北討董卓，頓軍城南，官署有井，每旦有五色氣從井出。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-001-142', 'p0087', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '進乃召董卓，欲以脅太后，魏書曰：太祖聞而笑之曰：「閹豎之官，古今宜有，但世主不當假之權寵，使至於此。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-001-143', 'p0087', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '」馥得移，請諸從事問曰：「今當助袁氏邪，助董卓邪？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-001-144', 'p0087', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '向使董卓聞山東兵起，倚王室之重，據二周之險，東向以臨天下；雖以無道行之，猶足為患。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-001-145', 'p0087', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '魏書載太祖荅紹曰：「董卓之罪，暴於四海，吾等合大衆興義兵，遠近莫不響應，此以義動故也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-001-146', 'p0087', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '興平元年春，太祖自徐州還，初，太祖父嵩去官後還譙，董卓之亂，避難琅邪，為陶謙所害，故太祖志在復讎東伐。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-001-147', 'p0087', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '而遭值董卓之難，興舉義兵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-001-148', 'p0087', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '昔者董卓初興國難，羣后釋位以謀王室，左氏傳曰：「諸侯釋位以間王政。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-001-149', 'p0087', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '會董卓作亂，義當死難，故敢奮身出命，摧鋒率衆，遂值千載之運，奉役目下。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-002-150', 'p0087', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '董卓乘釁，惡甚澆、𤡬，劫遷省御太僕宮廟，遂使九州幅裂，彊敵虎爭，華夏鼎沸，蝮蛇塞路。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-002-151', 'p0087', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '評曰：文帝天資文藻，下筆成章，博聞彊識，才藝兼該；典論帝自敘曰：初平之元，董卓殺主鴆后，盪覆王室。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-003-152', 'p0087', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '」於是贈冊曰：「嗚呼，昔皇天降戾于漢，俾逆臣董卓，播厥凶虐，焚滅京都，劫遷大駕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-005-153', 'p0087', 'sanguozhi', 'a04-005', '《三國志·魏書五》', '及董卓為亂，太祖微服東出避難。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-006-154', 'p0087', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '董卓字仲穎，隴西臨洮人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-006-155', 'p0087', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '」又趨陳留王，曰：「我董卓也，從我抱來。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-006-156', 'p0087', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '」傕等曰：「董卓忠於陛下，而無故為呂布所殺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-006-157', 'p0087', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '華嶠曰：夫士以正立，以謀濟，以義成，若王允之推董卓而分其權，伺其間而弊其罪。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-006-158', 'p0087', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '又於朝廷省門外，為董卓作神坐，數以牛羊祠之，訖，過省閤問起居，求入見。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-006-159', 'p0087', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '乃召董卓，欲以脅太后。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-006-160', 'p0087', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '董卓呼紹，議欲廢帝，立陳留王。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-006-161', 'p0087', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '說紹曰：「將軍弱冠登朝，則播名海內；值廢立之際，則忠義奮發；單騎出奔，則董卓懷怖；濟河而北，則勃海稽首。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-006-162', 'p0087', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '謝承後漢書曰：班，王匡之妹夫，董卓使班奉詔到河內，解釋義兵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-006-163', 'p0087', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '僕與董卓有何親戚，義豈同惡？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-006-164', 'p0087', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '」　英雄記載太祖作董卓歌，辭云：「德行不虧缺，變故自難常。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-006-165', 'p0087', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '續遇董卓侵官暴國，於是提劒揮鼓，發命東夏，方收羅英雄，棄瑕錄用，故遂與操參咨策略，謂其鷹犬之才，爪牙可任。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-006-166', 'p0087', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '初，紹去董卓出奔，與許攸及紀俱詣兾州，紹以紀聦達有計策，甚親信之，與共舉事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-006-167', 'p0087', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '董卓之將廢帝，以術為後將軍；術亦畏卓之禍，出奔南陽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-006-168', 'p0087', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '評曰：董卓狼戾賊忍，暴虐不仁，自書契已來，殆未之有也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-006-169', 'p0087', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '董卓自竊權柄，至于隕斃，計其日月，未盈三周，而禍崇山岳，毒流四海。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-007-170', 'p0087', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '進敗，董卓入京都，將為亂，欲殺原，并其兵衆。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-007-171', 'p0087', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '董卓之亂，太祖與邈首舉義兵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-007-172', 'p0087', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '布見關東起兵，欲誅董卓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-007-173', 'p0087', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '術報書曰：「昔董卓作亂，破壞王室，禍害術門戶，術舉兵關東，未能屠裂卓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-007-174', 'p0087', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '布有殺董卓之功，與二將軍俱為功臣，可因今共擊破術，建功於天下，此時不可失也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-007-175', 'p0087', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '布與建書曰：「天下舉兵，本以誅董卓爾。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-007-176', 'p0087', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '高順諫曰：「將軍躬殺董卓，威震夷狄，端坐顧盼，遠近自然畏服，不宜輕自出軍；如或不捷，損名非小。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-007-177', 'p0087', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '董卓殺帝，圖危社稷，洪說超曰：「明府歷世受恩，兄弟並據大郡，今王室將危，賊臣未梟，此誠天下義烈報恩効命之秋也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-007-178', 'p0087', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '洪乃升壇操槃歃血而盟曰：「漢室不幸，皇綱失統，賊臣董卓乘釁縱害，禍加至尊，虐流百姓，大懼淪喪社稷，剪覆四海。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-008-179', 'p0087', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '會董卓至洛陽，遷虞大司馬，瓚奮武將軍，封薊侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-008-180', 'p0087', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '昔為司隷校尉，會值國家喪禍之際，太后承攝，何氏輔政，紹專為邪媚，不能舉直，至令丁原焚燒孟津，招來董卓，造為亂根，紹罪一也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-008-181', 'p0087', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '紹為勃海太守，默選戎馬，當攻董卓，不告父兄，至使太傅門戶、太僕母子一旦而斃，不仁不孝，紹罪三也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-008-182', 'p0087', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '又長沙太守孫堅，前領豫州刺史，驅走董卓，掃除陵廟，其功莫大；紹令周昂盜居其位，斷絕堅糧，令不得入，使卓不被誅，紹罪十也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-008-183', 'p0087', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '董卓之亂，州郡起兵，天子都長安，四方斷絕，謙遣使間行致貢獻，遷安東將軍、徐州牧，封溧陽侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-008-184', 'p0087', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '同郡徐榮為董卓中郎將，薦度為遼東太守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-008-185', 'p0087', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '是後，董卓遷天子於長安，天下兵數起，燕遂以其衆與豪傑相結。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-008-186', 'p0087', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '董卓敗，濟與李傕等擊呂布，為卓報仇。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-009-187', 'p0087', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '太守王匡以為從事，將兵拒董卓於盟津。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-009-188', 'p0087', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '太祖起義兵討董卓，至熒陽，為卓將徐榮所敗。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-010-189', 'p0087', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '董卓秉政，復徵爽，爽欲遁去，吏持之急。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-010-190', 'p0087', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '是時，董卓威陵天下，太祖以問彧，彧曰：「卓暴虐已甚，必以亂終，無能為也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-010-191', 'p0087', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '前討徐州，威罰實行，曹瞞傳云：自京師遭董卓之亂，人民流移東出，多依彭城間。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-010-192', 'p0087', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '董卓之亂，關東兵起，卓徙都長安。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-010-193', 'p0087', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '攸與議郎鄭泰、何顒、侍中种輯、越騎校尉伍瓊等謀曰：「董卓無道，甚於桀紂，天下皆怨之，雖資彊兵，實一匹夫耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-010-194', 'p0087', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '遷北軍中候，董卓以為長史。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-010-195', 'p0087', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '董卓之入洛陽，詡以太尉掾為平津都尉，遷討虜校尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-011-196', 'p0087', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '董卓作亂，承欲合徒衆與天下共誅卓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-011-197', 'p0087', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '初平元年，義兵起，董卓遷帝于長安。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-011-198', 'p0087', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '會董卓作亂，避地遼東，躬秉農器，編於四民，布衣蔬食，不改其樂。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-012-199', 'p0087', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '信至京師，董卓亦始到。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-013-200', 'p0087', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '董卓遷天子長安，歆求出為下邽令，病不行，遂從藍田至南陽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-014-201', 'p0087', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '曄進曰：「明公以步卒五千，將誅董卓，北破袁紹，南征劉表，九州百郡，十并其八，威震天下，勢慴海外。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-014-202', 'p0087', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '太祖克兾州，放說松曰：「往者董卓作逆，英雄並起，阻兵擅命，人自封殖，惟曹公能拔拯危亂，翼戴天子，奉辭伐罪，所向必克。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-015-203', 'p0087', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '是時董卓遷天子都長安，卓因留洛陽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-015-204', 'p0087', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '到謂父老曰；「董卓悖逆，為天下所讎，此忠臣義士奮發之時也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-016-205', 'p0087', 'sanguozhi', 'a04-016', '《三國志·魏書十六》', '峻說原曰：「董卓首亂，天下莫不側目，然而未有先發者，非無其心也，勢未敢耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-016-206', 'p0087', 'sanguozhi', 'a04-016', '《三國志·魏書十六》', '渾兄泰，與荀攸等謀誅董卓，為揚州刺史，卒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-016-207', 'p0087', 'sanguozhi', 'a04-016', '《三國志·魏書十六》', '進將誅黃門，欲召董卓為助，泰謂進曰：「董卓彊忍寡義，志欲無饜，若借之朝政，授之大事，將肆其心以危朝廷。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-017-208', 'p0087', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '還，進敗，以兵屬董卓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-022-209', 'p0087', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '從討董卓，戰于熒陽而卒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-022-210', 'p0087', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '董卓作亂，漢室傾蕩，太祖到陳留，始與茲相見，遂同盟，計興武事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-022-211', 'p0087', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '董卓議欲廢帝，衆莫敢對，植獨正言，語在卓傳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-023-212', 'p0087', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '太守王匡起兵討董卓，遣諸生於屬縣微伺吏民罪負，便收之，考責錢穀贖罪，稽遲則夷滅宗族，以崇威嚴。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-028-213', 'p0087', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '叔父允，為漢司徒，誅董卓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-028-214', 'p0087', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '郡有董卓塢，為之宮舍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-031-215', 'p0087', 'sanguozhi', 'a04-031', '《三國志·蜀書一》', '英雄記曰：劉焉起兵，不與天下討董卓，保州自守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-031-216', 'p0087', 'sanguozhi', 'a04-031', '《三國志·蜀書一》', '董卓使司徒趙謙將兵向州，說校尉賈龍，使引兵還擊焉，焉出青羌與戰，故能破殺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-031-217', 'p0087', 'sanguozhi', 'a04-031', '《三國志·蜀書一》', '時焉子範為左中郎將，誕治書御史，璋為奉車都尉，皆從獻帝在長安，英雄記曰：範父焉為益州牧，董卓所徵發，皆不至。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-032-218', 'p0087', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '會靈帝崩，天下大亂，備亦起軍從討董卓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-032-219', 'p0087', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '董卓欲以所私並充臺閣，戩拒不聽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-032-220', 'p0087', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '董卓首難，蕩覆京畿，曹操階禍，竊執天衡；皇后太子鴆殺見害，剥亂天下，殘毀民物。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-032-221', 'p0087', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '曩者董卓造為亂階，自是之後，羣兇縱橫，殘剥海內。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-033-222', 'p0087', 'sanguozhi', 'a04-033', '《三國志·蜀書三》', '曩者漢祚中微，網漏凶慝，董卓造難，震蕩京畿。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-035-223', 'p0087', 'sanguozhi', 'a04-035', '《三國志·蜀書五》', '」亮荅曰：「自董卓已來，豪傑並起，跨州連郡者不可勝數。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-037-224', 'p0087', 'sanguozhi', 'a04-037', '《三國志·蜀書七》', '盛又譏其受任非所，將謂仕於董卓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-038-225', 'p0087', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '靈帝崩，董卓秉政，以漢陽周毖為吏部尚書，與靖共謀議，進退天下之士，沙汰穢濁，顯拔幽滯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-039-226', 'p0087', 'sanguozhi', 'a04-039', '《三國志·蜀書九》', '時孫堅舉兵討董卓，以南陽太守張咨不給軍糧，殺之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-046-227', 'p0087', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '董卓見儁，外甚親納，而心忌之，儁亦陰備焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-046-228', 'p0087', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '」儁曰：「相國董卓為臣說之，臣聞之於相國。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-046-229', 'p0087', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '英雄記曰：初堅討董卓，到梁縣之陽人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-046-230', 'p0087', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '先君與袁氏共破董卓，功業未遂，卒為黃祖所害。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-046-231', 'p0087', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '」　江表傳曰：策徑到壽春見袁術，涕泣而言曰：「亡父昔從長沙入討董卓，與明使君會於南陽，同盟結好；不幸遇難，勳業不終。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-046-232', 'p0087', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '曩日之舉義兵也，天下之士所以響應者，董卓擅廢置，害太后、弘農王，略烝宮人，發掘園陵，暴逆至此，故諸州郡雄豪聞聲慕義。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-046-233', 'p0087', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '江表傳曰：建安二年夏，漢朝遣議郎王誧奉戊辰詔書曰：「董卓逆亂，凶國害民。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-047-234', 'p0087', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '其司州之土，以函谷關為界，造為盟曰：「天降喪亂，皇綱失叙，逆臣承釁，劫奪國柄，始於董卓，終於曹操，窮凶極惡，以覆四海，至令九州幅裂，普天無統，民神痛怨，靡所戾止。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-049-235', 'p0087', 'sanguozhi', 'a04-049', '《三國志·吳書四》', '董卓作亂，壹亡歸鄉里。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-053-236', 'p0087', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '紘以破虜有破走董卓，扶持漢室之勳；討逆平定江外，建立大業，宜有紀頌以昭公美。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-054-237', 'p0087', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '初，孫堅興義兵討董卓，徙家於舒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-055-238', 'p0087', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '從孫堅征伐，討黃巾於宛、鄧，破董卓於陽人，攻城野戰，身被創夷。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-055-239', 'p0087', 'sanguozhi', 'a04-055', '《三國志·吳書十》', '堅南破山賊，北走董卓，拜蓋別部司馬。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-056-240', 'p0087', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '從破董卓於陽人，入洛陽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-056-241', 'p0087', 'sanguozhi', 'a04-056', '《三國志·吳書十一》', '治聞之，求往見賁，為陳安危，江表傳載治說賁曰：「破虜將軍昔率義兵入討董卓，聲冠中夏，義士壯之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-057-242', 'p0087', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '陳國陳融、陳留濮陽逸、沛郡蔣纂、廣陵袁迪等，皆單貧有志，就瑁游處，迪孫曄，字思光，作獻帝春秋，云迪與張紘等俱過江，迪父綏為太傅掾，張超之討董卓，以綏領廣陵事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0087-a04-060-243', 'p0087', 'sanguozhi', 'a04-060', '《三國志·吳書十五》', '父柔，漢靈帝時舉孝廉，補尚書郎右丞，董卓之亂，棄官歸，州辟別駕從事，詔書就拜會稽東部都尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a03-009-0', 'p0088', 'houhanshu', 'a03-009', '《後漢書·卷九》', '十二月癸酉，曹操擊呂布於徐州，斬之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a03-058-1', 'p0088', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '魏志呂布傳曰：「布破張燕軍而求益兵，衆將士鈔掠，紹患忌之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a03-058-2', 'p0088', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '先是洪遣司馬二人出，求救於呂布。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a03-066-3', 'p0088', 'houhanshu', 'a03-066', '《後漢書·卷六十六》', '」允然其言，乃潛結卓將呂布，使為內應。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a03-066-4', 'p0088', 'houhanshu', 'a03-066', '《後漢書·卷六十六》', '會卓入賀，呂布因刺殺之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a03-066-5', 'p0088', 'houhanshu', 'a03-066', '《後漢書·卷六十六》', '允初議赦卓部曲，呂布亦數勸之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a03-066-6', 'p0088', 'houhanshu', 'a03-066', '《後漢書·卷六十六》', '」呂布又欲以卓財物班賜公卿、將校，允又不從。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a03-070-7', 'p0088', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '」曰：「何知貢不與呂布同謀，而輕欲見之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a03-070-8', 'p0088', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '二年，陶謙死，操欲遂取徐州，還定呂布。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a03-070-9', 'p0088', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '宜急分討陳宮，使虜不得西顧，乘其閒而收熟麥，約食稸穀，以資一舉，則呂布不足破也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a03-070-10', 'p0088', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '彧量紹雖強，終為操所制，乃說先取呂布，然後圖紹，操從之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a03-070-11', 'p0088', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '三年，遂擒呂布，定徐州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a03-072-12', 'p0088', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '尋而何進及弟苗先所領部曲皆歸於卓，卓又使呂布殺執金吾丁原而并其衆，英雄記曰：「原字建陽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a03-072-13', 'p0088', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '又使呂布發諸帝陵，及公卿已下冢墓，收其珍寶。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a03-072-14', 'p0088', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '卓遣將胡軫、呂布攻之，布與軫不相能，軍中自驚恐，士卒散亂。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a03-072-15', 'p0088', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '九州春秋曰：「卓以東郡太守胡軫為大督，呂布為騎督。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a03-072-16', 'p0088', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '時王允與呂布及僕射士孫瑞謀誅卓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a03-072-17', 'p0088', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '英雄記曰：「有道士書布為『呂』字，將以示卓，卓不知其為呂布也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a03-072-18', 'p0088', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '乃陳兵夾道，自壘及宮，左步右騎，屯衞周帀，令呂布等扞衞前後。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a03-072-19', 'p0088', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '王允乃與士孫瑞密表其事，使瑞自書詔以授布，令騎都尉李肅獻帝紀曰：「肅，呂布同郡人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a03-072-20', 'p0088', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '肅以戟刺之，卓衷甲不入，傷臂墯車，顧大呼曰：「呂布何在？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a03-072-21', 'p0088', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '呂布乃使李肅以詔命至陝討輔等，輔等逆與肅戰，肅敗走弘農，布誅殺之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a03-072-22', 'p0088', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '傕、汜等以王允、呂布殺董卓，故忿怒并州人，并州人其在軍者男女數百人，皆誅殺之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a03-072-23', 'p0088', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '城峻不可攻，守之八日，呂布軍有叟兵內反，叟兵即蜀兵也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a03-072-24', 'p0088', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '魏志曰：「楊素與呂布善。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a03-073-25', 'p0088', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '會張邈迎呂布據兖州，操還擊布。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a03-074-26', 'p0088', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '曹洪以馬與操，得夜遁，又為呂布所敗。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a03-074-27', 'p0088', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '自是士林憤痛，人怨天怒，一夫奮臂，舉州同聲，故躬破於徐方，地奪於呂布，魏志曰：「陶謙為徐州牧，操初征之，下十餘城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a03-074-28', 'p0088', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '還過郯，會張邈與陳宮畔迎呂布，郡縣皆應。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a03-075-29', 'p0088', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '乃遣使以竊號告呂布，并為子娉布女。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a03-075-30', 'p0088', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '呂布字奉先，五原九原人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a03-075-31', 'p0088', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '布常御良馬，號曰赤菟，能馳城飛塹，曹瞞傳曰：「時人語曰：『人中有呂布，馬中有赤菟。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a03-075-32', 'p0088', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '今州軍東征，其處空虛，呂布壯士，善戰無前，迎之共據兖州，觀天下形埶，俟時事變通，此亦從橫一時也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a03-075-33', 'p0088', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '後從征呂布，為流矢傷左目。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a03-075-34', 'p0088', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '宋武北征記曰：「下邳城有三重，大城周四里，呂布所守也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a03-075-35', 'p0088', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '明公不見呂布事丁建陽、董太師乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a03-096-36', 'p0088', 'houhanshu', 'a03-096', '《二十四史-後漢書-志第六‧禮儀下》', '」臣昭案：董卓傳：「卓使呂布發諸帝陵及公卿以下冢墓，收其珍寶。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a03-102-37', 'p0088', 'houhanshu', 'a03-102', '《二十四史-後漢書-志第十二‧天文下》', '及司徒王允與將軍呂布誅卓，卓部曲將郭汜、李傕旋兵攻長安，公卿百官吏民戰死者且萬人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a03-103-38', 'p0088', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '至三年夏，司徒王允使中郎將呂布殺太師董卓，夷三族。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-001-39', 'p0088', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '夏四月，司徒王允與呂布共殺卓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-001-40', 'p0088', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '會張邈與陳宮叛迎呂布，郡縣皆應。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-001-41', 'p0088', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '袁術欲稱帝於淮南，使人告呂布。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-001-42', 'p0088', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '」呂布復為袁術使高順攻劉備，公遣夏侯惇救之，不利。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-001-43', 'p0088', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '諸將皆疑，荀攸勸公許之，魏書曰：公云：「我攻呂布，表不為寇，官渡之役，不救袁紹，此自守之賊也，宜為後圖。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-001-44', 'p0088', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '迴戈東征，呂布就戮，乘轅將返，張楊殂斃，眭固伏罪，張繡稽服，此又君之功也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-003-45', 'p0088', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '獻帝傳曰：朗父名宜祿，為呂布使詣袁術，術妻以漢宗室女。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-006-46', 'p0088', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '卓又使呂布殺執金吾丁原，并其衆，故京都兵權唯在卓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-006-47', 'p0088', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '三年四月，司徒王允、尚書僕射士孫瑞、卓將呂布共謀誅卓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-006-48', 'p0088', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '又有道士書布為「呂」字以示卓，卓不知其為呂布也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-006-49', 'p0088', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '卓死，呂布使李肅至陝，欲以詔命誅輔。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-006-50', 'p0088', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '」傕等曰：「董卓忠於陛下，而無故為呂布所殺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-006-51', 'p0088', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '詣傕，傕不肯，曰：「我有討呂布之功，輔政四年，三輔清靜，天下所知也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-006-52', 'p0088', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '近董公之彊，明將軍目所見，內有王公以為內主，外有董旻、承、璜以為鯁毒，呂布受恩而反圖之，斯須之間，頭縣竿端，此有勇而無謀也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-006-53', 'p0088', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '自是士林憤痛，民怨彌重，一夫奮臂，舉州同聲，故躬破於徐方，地奪於呂布，仿偟東裔，蹈據無所。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-006-54', 'p0088', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '術前為呂布所破，後為太祖所敗，奔其部曲雷薄、陳蘭於灊山，復為所拒，憂懼不知所出。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-007-55', 'p0088', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '呂布字奉先，五原郡九原人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-007-56', 'p0088', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '曹瞞傳曰：時人語曰：「人中有呂布，馬中有赤兎。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-007-57', 'p0088', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '呂布之捨袁紹從張楊也，過邈臨別，把手共誓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-007-58', 'p0088', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '今州軍東征，其處空虛，呂布壯士，善戰無前，若權迎之，共牧兖州，觀天下形勢，俟時事之變通，此亦縱橫之一時也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-007-59', 'p0088', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '及天下亂，始隨太祖，後自疑，乃從呂布，為布畫策，布每不從其計。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-007-60', 'p0088', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '又掎角呂布有功，加伏波將軍，年三十九卒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-007-61', 'p0088', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '奉使到許，太祖以登為廣陵太守，令陰合衆以圖呂布。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-007-62', 'p0088', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '袁、曹方睦，夾輔王室，呂布反覆無義，志在逆亂，而邈、超擅立布為州牧，其於王法，乃一罪人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-007-63', 'p0088', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '」先是，洪遣司馬二人出，求救於呂布；比還，城已陷，皆赴敵死。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-007-64', 'p0088', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '評曰：呂布有虓虎之勇，而無英奇之略，輕狡反覆，唯利是視。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-008-65', 'p0088', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '會張邈叛迎呂布，太祖還擊布。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-008-66', 'p0088', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '董卓敗，濟與李傕等擊呂布，為卓報仇。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-009-67', 'p0088', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '張邈叛迎呂布，太祖家在鄄城，惇輕軍往赴，適與布會，交戰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-009-68', 'p0088', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '太祖自徐州還，惇從征呂布，為流矢所中，傷左目。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-009-69', 'p0088', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '太祖征呂布，仁別攻勾陽，拔之，生獲布將劉何。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-009-70', 'p0088', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '太祖征徐州，張邈舉兖州叛迎呂布。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-010-71', 'p0088', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '會張邈、陳宮以兖州反，潛迎呂布。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-010-72', 'p0088', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '豫州刺史郭貢帥衆數萬來至城下，或言與呂布同謀，衆甚懼。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-010-73', 'p0088', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '太祖方東憂呂布，南拒張繡，而繡敗太祖軍於宛。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-010-74', 'p0088', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '彧曰：「不先取呂布，河北亦未易圖也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-010-75', 'p0088', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '三年，太祖旣破張繡，東禽呂布，定徐州，遂與袁紹相拒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-010-76', 'p0088', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '是歲，太祖自宛征呂布，魏書曰：議者云表、繡在後而還襲呂布，其危必也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-010-77', 'p0088', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '攸與郭嘉說曰：「呂布勇而無謀，今三戰皆北，其銳氣衰矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-011-78', 'p0088', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '頃之，呂布擊術於阜陵，渙往從之，遂復為布所拘留。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-011-79', 'p0088', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '」又帝聞渙昔拒呂布之事，問渙從弟敏：「渙勇怯何如？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-014-80', 'p0088', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '張邈等叛迎呂布，郡縣響應，唯鄄城、范、東阿不動。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-014-81', 'p0088', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '」昱乃歸，過范，說其令靳允曰：「聞呂布執君母弟妻子，孝子誠不可為心！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-014-82', 'p0088', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '陳宮叛迎呂布而百城皆應，似能有為，然以君觀之，布何如人哉！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-014-83', 'p0088', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '太祖與呂布戰於濮陽，數不利。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-014-84', 'p0088', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '」嘉又曰：「紹方北擊公孫瓚，可因其遠征，東取呂布。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-014-85', 'p0088', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '征呂布，三戰破之，布退固守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-014-86', 'p0088', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '自在軍旅，十有餘年，行同騎乘，坐共幄席，東禽呂布，西取眭固，斬袁譚之首，平朔土之衆，踰越險塞，盪定烏丸，震威遼東，以梟袁尚。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-015-87', 'p0088', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '乆之，關東兵散，太祖與呂布相持於濮陽，朗乃將家還溫。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-016-88', 'p0088', 'sanguozhi', 'a04-016', '《三國志·魏書十六》', '呂布之亂，兖州皆叛，惟范、東阿完在，由祗以兵據城之力也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-017-89', 'p0088', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '卓敗，以兵屬呂布，遷騎都尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-017-90', 'p0088', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '太祖破呂布於下邳，遼將其衆降，拜中郎將，賜爵關內侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-017-91', 'p0088', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '從擊呂布於濮陽，張超於雍丘，橋蕤於苦，皆先登有功，封廣昌亭侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-017-92', 'p0088', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '從征張繡於安衆，圍呂布於下邳，破別將，擊眭固於射犬，攻劉備於沛，皆破之，拜討寇校尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-017-93', 'p0088', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '從討呂布於濮陽，別破布二營於城南，又別將破高雅於須昌。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-017-94', 'p0088', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '復從攻張繡於穰，禽呂布於下邳，別與史渙、曹仁攻眭固於射犬，破斬之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-017-95', 'p0088', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '從征呂布，別降布將趙庶、李鄒等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-018-96', 'p0088', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '呂布之亂，太祖遣乾還乘氏，慰勞諸縣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-018-97', 'p0088', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '太祖之討呂布也，霸等將兵助布。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-018-98', 'p0088', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '太祖破呂布，使霸招觀兄弟，皆厚遇之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-022-99', 'p0088', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '呂布若襲將軍之後，將軍雖得徐州，事必無成。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-022-100', 'p0088', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '屬呂布破，太祖辟羣為司空西曹掾屬。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-032-101', 'p0088', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '先主與術相持經月，呂布乘虛襲下邳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-032-102', 'p0088', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '豹衆堅營自守，使人招呂布。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-032-103', 'p0088', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '先主求和於呂布，布還其妻子。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-032-104', 'p0088', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '呂布惡之，自出兵攻先主，先主敗走歸曹公。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-036-105', 'p0088', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '蜀記曰：曹公與劉備圍呂布於下邳，關羽啟公，布使秦宜祿行求救，乞娶其妻，公許之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-036-106', 'p0088', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '先主從曹公破呂布，隨還許，曹公拜飛為中郎將。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-038-107', 'p0088', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '建安元年，呂布乘先主之出拒袁術，襲下邳，虜先主妻子。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-046-108', 'p0088', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '卓亦遣兵步騎五千迎之，陳郡太守胡軫為大督護，呂布為騎督，其餘步騎將校都督者甚衆。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-053-109', 'p0088', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '表為正議校尉，吳書曰：紘與張昭並與參謀，常令一人居守，一人從征討，後呂布襲取徐州，因為之牧，不欲令紘與策從事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0088-a04-054-110', 'p0088', 'sanguozhi', 'a04-054', '《三國志·吳書九》', '」權曰：「老賊欲廢漢自立乆矣，徒忌二袁、呂布、劉表與孤耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0089-a03-070-0', 'p0089', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '會張邈、陳宮以兖州反操，典略「宮字公臺，東郡人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0089-a03-070-1', 'p0089', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '宜急分討陳宮，使虜不得西顧，乘其閒而收熟麥，約食稸穀，以資一舉，則呂布不足破也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0089-a03-074-2', 'p0089', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '還過郯，會張邈與陳宮畔迎呂布，郡縣皆應。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0089-a03-074-3', 'p0089', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '布復與陳宮將萬餘人來戰，操時兵少，設伏縱竒兵擊，大破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0089-a03-075-4', 'p0089', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '興平元年，曹操東擊陶謙，令其將武陽人陳宮屯東郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0089-a03-075-5', 'p0089', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '典略曰：「陳宮字公臺，東郡人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0089-a03-075-6', 'p0089', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '布欲降，而陳宮等自以負罪於操，深沮其計，而謂布曰：「曹公遠來，埶不能乆。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0089-a03-075-7', 'p0089', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '」成忿懼，乃與諸將共執陳宮、高順，率其衆降。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0089-a03-075-8', 'p0089', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '」酈元水經注曰：「南門謂之白門，魏武禽陳宮於此。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0089-a03-075-9', 'p0089', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '」操謂陳宮曰：「公臺平生自謂智有餘，今意何如？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0089-a04-001-10', 'p0089', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '世語曰：岱旣死，陳宮謂太祖曰：「州今無主，而王命斷絕，宮請說州中，明府尋往牧之，資之以收天下，此霸王之業也。');
